export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

export const MAX_ATTEMPTS = 3;
export const TRANSIENT_ERROR = 'transient failure';
/** A worker that has not written a heartbeat for this long is reported as down. */
export const HEARTBEAT_STALE_MS = 3_000;

export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

interface Row {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  payload: string | null;
  created_at: string;
  updated_at: string;
}

export interface ClaimedJob {
  id: string;
  input: string;
  steps: number;
  failAttempts: number;
  /** The attempt number now running (1-based). */
  attempt: number;
}

function toJob(row: Row): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

