  private readonly selectById: StatementSync;
  private readonly selectByKey: StatementSync;
  private readonly selectAll: StatementSync;
  private readonly selectNext: StatementSync;
  private readonly startAttempt: StatementSync;
  private readonly updateProgress: StatementSync;
  private readonly complete: StatementSync;
  private readonly failToFailed: StatementSync;
  private readonly failToQueued: StatementSync;
  private readonly recover: StatementSync;
  private readonly beat: StatementSync;
  private readonly selectBeat: StatementSync;
  private readonly clearBeat: StatementSync;

  constructor(private readonly db: DatabaseSync) {
    this.insert = db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, payload, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
    );
    this.selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
    this.selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
    this.selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
    this.selectNext = db.prepare(
      "SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1",
    );
    this.startAttempt = db.prepare(
      "UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, updated_at = ? WHERE id = ?",
    );
    this.updateProgress = db.prepare(
      "UPDATE jobs SET completed = ?, updated_at = ? WHERE id = ? AND attempts = ? AND status = 'running'",
    );
    this.complete = db.prepare(
      "UPDATE jobs SET status = 'completed', result_output = ?, completed = steps, updated_at = ? WHERE id = ? AND attempts = ? AND status = 'running'",
    );
    this.failToFailed = db.prepare(
      "UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE id = ? AND attempts = ? AND status = 'running'",
    );
    this.failToQueued = db.prepare(
      "UPDATE jobs SET status = 'queued', completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND attempts = ? AND status = 'running'",
    );
    this.recover = db.prepare(
      "UPDATE jobs SET status = 'queued', completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'",
    );
    this.beat = db.prepare(
      'INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT (id) DO UPDATE SET beat_at = excluded.beat_at',
    );
    this.selectBeat = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1');
    this.clearBeat = db.prepare('DELETE FROM worker_heartbeat WHERE id = 1');
  }

  createJob(input: string, steps: number, failAttempts: number, key: string | null, payload: string | null): Job {
    const id = randomUUID();
    const now = new Date().toISOString();
    this.insert.run(id, input, steps, failAttempts, key, payload, now, now);
    return this.getJob(id)!;
  }

  getJob(id: string): Job | undefined {
    const row = this.selectById.get(id) as unknown as Row | undefined;
    return row ? toJob(row) : undefined;
  }

  /** Returns the job created under an idempotency key, with the payload it was created from. */
  findByKey(key: string): { job: Job; payload: string | null } | undefined {
    const row = this.selectByKey.get(key) as unknown as Row | undefined;
    return row ? { job: toJob(row), payload: row.payload } : undefined;
  }

  listJobs(): Job[] {
    return (this.selectAll.all() as unknown as Row[]).map(toJob);
  }

  writeHeartbeat(now: number): void {
    this.beat.run(now);
  }

  clearHeartbeat(): void {
    this.clearBeat.run();
  }

  workerUp(now: number): boolean {
    const row = this.selectBeat.get() as { beat_at: number } | undefined;
    return row !== undefined && now - row.beat_at < HEARTBEAT_STALE_MS;
  }

  /** Requeues jobs left `running` by a worker that stopped without finishing them. Returns how many. */
  recoverInterrupted(now: number): number {
    return Number(this.recover.run(now).changes);
  }

  /** Moves the oldest eligible queued job to running and starts a new attempt. */
  claimNext(now: number): ClaimedJob | undefined {
    return this.transaction(() => {
      const next = this.selectNext.get(now) as { id: string } | undefined;
      if (!next) return undefined;
      this.startAttempt.run(now, next.id);
      const row = this.selectById.get(next.id) as unknown as Row;
      return {
        id: row.id,
        input: row.input,
        steps: row.steps,
        failAttempts: row.fail_attempts,
        attempt: row.attempts,
      };
    });
  }

  reportProgress(id: string, attempt: number, completed: number): void {
    this.updateProgress.run(completed, new Date().toISOString(), id, attempt);
  }

  finishCompleted(id: string, attempt: number, output: string): void {
    this.complete.run(output, new Date().toISOString(), id, attempt);
  }

  /** Records a failed attempt: requeues it with a delay, or marks it failed when no attempts remain. */
  finishFailedAttempt(id: string, attempt: number, retryAt: number): 'queued' | 'failed' {
    const now = new Date().toISOString();
    if (attempt >= MAX_ATTEMPTS) {
      this.failToFailed.run(TRANSIENT_ERROR, now, id, attempt);
      return 'failed';
    }
    this.failToQueued.run(retryAt, now, id, attempt);
    return 'queued';
  }

  private transaction<T>(fn: () => T): T {
    this.db.exec('BEGIN IMMEDIATE');
    try {
      const result = fn();
      this.db.exec('COMMIT');
      return result;
    } catch (e) {
      this.db.exec('ROLLBACK');
      throw e;
    }
  }
}

