test('restart during the third attempt of a job that can succeed completes on attempt 3', () => {
  const store = fresh();
  const job = store.createJob('ok', 1, 2, null, null);
  for (let n = 1; n <= 2; n++) {
    const c = claim(store, Date.now());
    store.finishFailedAttempt(c.id, c.attempt, 0);
  }
  claim(store, Date.now());
  store.recoverInterrupted(Date.now());
  const retried = claim(store, Date.now());
  assert.equal(retried.attempt, 3);
  store.finishCompleted(retried.id, retried.attempt, retried.input.toUpperCase());

  const done = store.getJob(job.id)!;
  assert.equal(done.status, 'completed');
  assert.deepEqual(done.result, { output: 'OK' });
  assert.equal(done.attempts, 3);
});

test('input and output round-trip exactly, including NUL and unpaired surrogates', () => {
  const store = fresh();
  for (const input of ['a\u0000b', '\ud800', 'x\udc00y\u0000']) {
    const job = store.createJob(input, 1, 0, null, null);
    assert.equal(job.input, input);
    const c = claim(store, Date.now());
    assert.equal(c.input, input);
    store.finishCompleted(c.id, c.attempt, c.input.toUpperCase());
    const done = store.getJob(job.id)!;
    assert.deepEqual(done.result, { output: input.toUpperCase() });
  }
});

test('updatedAt is ISO 8601 after an attempt starts and after recovery', () => {
  const store = fresh();
  const job = store.createJob('ts', 1, 0, null, null);
  claim(store, Date.now());
  assert.match(store.getJob(job.id)!.updatedAt, ISO);
  store.recoverInterrupted(Date.now());
  assert.match(store.getJob(job.id)!.updatedAt, ISO);
});
